package report

import (
	"fmt"
	"maps"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/Demonisreal/dmn-ledger/bench/control"
	"github.com/Demonisreal/dmn-ledger/bench/load"
	"github.com/Demonisreal/dmn-ledger/bench/raw"
)

const intro = "# Benchmark results\n\n" +
	"Generated by `bench report` from the files in `raw/`; the same files give the same bytes. Change the raw files, " +
	"not this file: `bench check` compares it with what the raw files give.\n\n" +
	"Each figure is the median over the counted runs of its row, with the smallest and the largest value in brackets; " +
	"\"runs\" says how many runs were counted out of how many were made. A run counts when it is valid and ran at the " +
	"disk speed of its row. A row shows the slow disk speed when any of its valid runs reached it, otherwise the fast " +
	"one, marked as such. Within a run only the valid seconds of its disk speed count. Latency is counted from the " +
	"moment a transfer was scheduled, not from the moment it was sent. \"flushes\" is a latency divided by the mean " +
	"flush time of the disk in the same run. p99.9 is listed for completeness and is not compared. \"seconds\" counts the " +
	"window seconds of the counted runs that entered the figures, out of all their window seconds, with the highest p99 " +
	"of a second that was left out. \"target cpu\" is the CPU time of the target processes divided by the hardware " +
	"threads they were given, the mean over the window. \"fsync per transfer, all nodes\" adds up the fsyncs of every " +
	"node of a cluster and divides them by the confirmed transfers. \"given up\" is the share of the transfers due in the " +
	"counted seconds that Postgres gave up after 20 tries; a stage where more than 1 % of the transfers due in the window were " +
	"given up counts as saturated. \"retries per transfer\" adds up the retries of the transfers due in the counted seconds, " +
	"booked or given up, and divides them by the transfers booked in them. thermal limit: seconds in which the thermal counter of a target core rose. On this laptop " +
	"that is every second in which a core runs at turbo; the clock stayed between 4.0 and 4.5 GHz.\n\n"

const unpacedNote = "unpaced: in most seconds of the window the target flushed the disk fewer than 20 times. The speed of the disk " +
	"cannot be told from so few flushes, and it mattered little: in each of these seconds the target used at least half a core, " +
	"so it was computing, not waiting for the disk. Every second of the window counts, and such runs are compared with each " +
	"other without asking for an equally fast disk.\n\n"

func unpaced(gs []*group) bool {
	return slices.ContainsFunc(gs, func(g *group) bool { return g.speed == control.Unpaced })
}

type section struct{ m, title, text string }

var known = []section{
	{"m2", "Fixed load (m2)", "How long does a transfer wait at a fixed, moderate load, and what do a million accounts, " +
		"a few hot accounts and two-phase transfers change? \"saturated at\" marks a target that did not hold the load."},
	{"m3", "Runs with a CPU profile (m3)", "The runs behind the CPU profile further down, with the binary built for profiling."},
	{"m4", "", ""},
	{"m5", "Price of the seal (m5)", "The same binary built with simbug, without and with LEDGER_BUG=B13, which leaves out " +
		"the fsync of meta after the log. Ratios are B against A, the medians at the same disk speed."},
	{"m6", "Chain and stamp (m6)", "Fixed load without and with a signing key. Ratios are B against A, the medians at the " +
		"same disk speed."},
	{"m7", "One follower missing (m7)", "Three nodes with one follower stopped after the setup, next to the healthy runs of m2."},
}

func render(in []*run) map[string][]byte {
	runs := slices.Clone(in)
	sortRuns(runs)
	gs := groups(runs)
	out := make(map[string][]byte)
	var b strings.Builder
	b.WriteString(intro)
	if unpaced(gs) {
		b.WriteString(unpacedNote)
	}
	var ms []string
	for _, g := range gs {
		if !slices.Contains(ms, g.m) {
			ms = append(ms, g.m)
		}
	}
	of := func(m string) []*group {
		return slices.DeleteFunc(slices.Clone(gs), func(g *group) bool { return g.m != m })
	}
	if slices.Contains(ms, "m1") {
		writeStages(&b, gs, out)
	}
	for _, k := range known {
		if !slices.Contains(ms, k.m) {
			continue
		}
		if k.m == "m4" {
			writeSnapshots(&b, runs)
			continue
		}
		fmt.Fprintf(&b, "## %s\n\n%s\n\n", k.title, k.text)
		writeFixed(&b, of(k.m))
		switch k.m {
		case "m2":
			writeTwoPhase(&b, of("m2"))
			writeAgainstUniform(&b, of("m2"))
		case "m5", "m6":
			writeAB(&b, of(k.m))
		case "m7":
			b.WriteString("The healthy runs of m2 with the same load:\n\n")
			writeFixed(&b, healthy(of("m7"), of("m2")))
		}
	}
	writeLoop(&b, gs)
	writeProfiles(&b, runs)
	for _, m := range ms {
		if m == "m1" || slices.ContainsFunc(known, func(k section) bool { return k.m == m }) {
			continue
		}
		fmt.Fprintf(&b, "## %s\n\n", m)
		writeFixed(&b, of(m))
	}
	writeRuns(&b, runs)
	out[Results] = []byte(b.String())
	return out
}

func writeContext(b *strings.Builder, runs []*run, gs []*group) {
	var commits, dates, machines []string
	for _, r := range runs {
		c := r.f.Build.Commit
		if r.f.Build.Dirty {
			c += " (with changes)"
		}
		if len(r.f.Build.Tags) > 0 {
			c += " built with " + strings.Join(r.f.Build.Tags, ",")
		}
		m := r.f.Machine
		mach := fmt.Sprintf("%s, %d threads, %.1f GiB RAM, %s (%s, %s %s), kernel %s, governor %s, turbo %s, power %s",
			m.CPU, m.Threads, float64(m.RAM)/(1<<30), m.Model, m.Disk, m.Filesystem, m.Mount, m.Kernel, m.Governor, m.Turbo, m.Power)
		for _, s := range []struct {
			list *[]string
			v    string
		}{{&commits, c}, {&dates, r.f.Started.Format("2006-01-02")}, {&machines, mach}} {
			if !slices.Contains(*s.list, s.v) {
				*s.list = append(*s.list, s.v)
			}
		}
	}
	slices.Sort(commits)
	slices.Sort(dates)
	slices.Sort(machines)
	var speeds []string
	for _, speed := range []control.Speed{control.Slow, control.Fast} {
		var flush []float64
		for _, g := range gs {
			if g.speed != speed {
				continue
			}
			for _, r := range g.counted {
				flush = append(flush, float64(bandOf(r.f, speed).Flush))
			}
		}
		if len(flush) > 0 {
			speeds = append(speeds, fmt.Sprintf("%v, mean flush %s ms", speed, median(flush).show(millis(0))))
		}
	}
	if slices.ContainsFunc(gs, func(g *group) bool { return g.speed == control.Unpaced && len(g.counted) > 0 }) {
		speeds = append(speeds, "unpaced, no flush time")
	}
	if len(speeds) == 0 {
		speeds = []string{"no counted run"}
	}
	fmt.Fprintf(b, "Commit %s; run on %s; machine: %s; disk speed: %s.\n\n",
		strings.Join(commits, ", "), strings.Join(dates, ", "), strings.Join(machines, "; "), strings.Join(speeds, "; "))
	if slices.ContainsFunc(gs, func(g *group) bool { return g.speed == control.Fast }) {
		b.WriteString("A second counts as fast by the mean time of its flushes, and fast flushes come about seven times as " +
			"often as slow ones: a fast second can have spent up to about two thirds of its time in slow flushes, a slow " +
			"second at most about a tenth in fast ones.\n\n")
	}
	if unpaced(gs) {
		b.WriteString(unpacedNote)
	}
}

func (g *group) held() string {
	n := 0
	for _, r := range g.counted {
		if r.f.Verdict.Saturated {
			n++
		}
	}
	switch {
	case len(g.counted) == 0:
		return "n/a"
	case n == 0:
		return "held"
	case n == len(g.counted):
		return "saturated at " + grouped(float64(g.rate))
	}
	return fmt.Sprintf("saturated at %s in %d of %d runs", grouped(float64(g.rate)), n, len(g.counted))
}

func (g *group) atLeast() bool {
	return slices.ContainsFunc(g.counted, func(r *run) bool { return r.f.Verdict.Limit == raw.LimitGenerator })
}

func secondsCell(counted, all int, worst float64, horizon time.Duration, thermal int) string {
	cell := fmt.Sprintf("%d of %d", counted, all)
	if all > counted {
		cell += ", worst excluded p99 " + millis(horizon)(worst) + " ms"
	}
	if thermal > 0 {
		cell += fmt.Sprintf(", thermal limit in %d", thermal)
	}
	return cell
}

func secondsOf(runs []*run, speed control.Speed, horizon time.Duration) string {
	if len(runs) == 0 {
		return "n/a"
	}
	var counted, all, thermal int
	var worst float64
	for _, r := range runs {
		n := bandOf(r.f, speed).Seconds
		counted += n
		all += n + r.f.Verdict.Excluded
		thermal += r.f.Verdict.Throttled
		if r.f.Verdict.Excluded > 0 {
			worst = max(worst, nanos(r.f.Verdict.ExcludedP99))
		}
	}
	return secondsCell(counted, all, worst, horizon, thermal)
}

func (g *group) seconds() string {
	return secondsOf(g.counted, g.speed, g.horizon())
}

func share(x float64) string {
	return percent(x) + "%"
}

func speedCell(s control.Speed) string {
	if s == control.Fast {
		return "fast (no slow run)"
	}
	return s.String()
}

func fixedRow(g *group) []string {
	ms := millis(g.horizon())
	tp := g.spread(func(x fig) float64 { return x.throughput }).show(grouped)
	if g.atLeast() {
		tp = "at least " + tp
	}
	text, _ := g.judge()
	flush, flushes := g.spread(func(x fig) float64 { return x.flush }).show(millis(0)), g.spread(func(x fig) float64 { return x.flushes }).show(fixed(1))
	if g.speed == control.Unpaced {
		flush, flushes = "n/a", "n/a"
	}
	return []string{
		name(g.target), strconv.Itoa(g.target.Lanes), g.workload, grouped(float64(g.rate)), g.held(), speedCell(g.speed),
		flush,
		fmt.Sprintf("%d of %d", len(g.counted), len(g.runs)),
		g.seconds(),
		g.spread(func(x fig) float64 { return x.p50 }).show(ms),
		flushes,
		g.spread(func(x fig) float64 { return x.p99 }).show(ms),
		g.spread(func(x fig) float64 { return x.p999 }).show(ms),
		tp,
		g.spread(func(x fig) float64 { return x.targetShare }).show(share),
		g.spread(func(x fig) float64 { return x.syncs }).show(fixed(3)),
		g.spread(func(x fig) float64 { return x.perRequest }).show(fixed(1)),
		g.spread(func(x fig) float64 { return x.retries }).show(fixed(3)),
		g.spread(func(x fig) float64 { return x.shed }).show(share),
		text,
	}
}

var fixedHead = []string{"target", "lanes", "load", "rate", "held", "speed", "flush ms", "runs", "seconds", "p50 ms", "p50 flushes",
	"p99 ms", "p99.9 ms", "throughput/s", "target cpu", "fsync per transfer, all nodes", "transfers per request", "retries per transfer",
	"given up", "agreement"}

func writeFixed(b *strings.Builder, gs []*group) {
	t := table{head: fixedHead}
	perNode := table{head: []string{"target", "lanes", "load", "rate", "speed", "runs", "fsync per transfer, leader", "fsync per transfer, one follower"}}
	var runs []*run
	for _, g := range gs {
		row := fixedRow(g)
		if e := distinct(g.target); e != "" {
			row[0] += ", " + e
		}
		t.add(row...)
		if n, leader, follower := g.roleSyncs(); n > 0 {
			perNode.add(row[0], row[1], row[2], row[3], row[5], strconv.Itoa(n), leader.show(fixed(3)), follower.show(fixed(3)))
		}
		runs = append(runs, g.runs...)
	}
	if len(t.rows) == 0 {
		return
	}
	t.write(b)
	if len(perNode.rows) > 0 {
		b.WriteString("Each node on its own:\n\n")
		perNode.write(b)
	}
	writeContext(b, runs, gs)
}

func writeTwoPhase(b *strings.Builder, gs []*group) {
	t := table{head: []string{"target", "lanes", "rate", "speed", "runs", "reserved p50 ms", "reserved p50 flushes", "reserved p99 ms", "settled p50 ms", "settled p99 ms"}}
	var runs []*run
	var shown []*group
	for _, g := range gs {
		if len(g.counted) == 0 || !figOf(g.counted[0].f, g.speed).reserveKnown {
			continue
		}
		ms := millis(g.horizon())
		inFlushes := g.spread(func(x fig) float64 { return x.reserveP50 / x.flush }).show(fixed(1))
		if g.speed == control.Unpaced {
			inFlushes = "n/a"
		}
		t.add(name(g.target), strconv.Itoa(g.target.Lanes), grouped(float64(g.rate)), speedCell(g.speed), strconv.Itoa(len(g.counted)),
			g.spread(func(x fig) float64 { return x.reserveP50 }).show(ms),
			inFlushes,
			g.spread(func(x fig) float64 { return x.reserveP99 }).show(ms),
			g.spread(func(x fig) float64 { return x.p50 }).show(ms),
			g.spread(func(x fig) float64 { return x.p99 }).show(ms))
		runs = append(runs, g.runs...)
		shown = append(shown, g)
	}
	if len(t.rows) == 0 {
		return
	}
	b.WriteString("Two-phase transfers: the wait until the reservation is answered, and until it is posted or voided.\n\n")
	t.write(b)
	writeContext(b, runs, shown)
}

func sameBut(a, b *group) bool {
	return a.target.Kind == b.target.Kind && a.target.Nodes == b.target.Nodes && a.target.Variant == b.target.Variant &&
		a.target.Lanes == b.target.Lanes && a.rate == b.rate
}

func writeAgainstUniform(b *strings.Builder, gs []*group) {
	t := table{head: []string{"target", "lanes", "rate", "load", "speed", "p50 against uniform-10k", "p99 against uniform-10k", "fsync per transfer against uniform-10k"}}
	var runs []*run
	var shown []*group
	for _, g := range gs {
		if g.workload == "uniform-10k" {
			continue
		}
		i := slices.IndexFunc(gs, func(base *group) bool {
			return base.workload == "uniform-10k" && sameBut(base, g) && env(base.target) == env(g.target) && slices.Equal(base.tags, g.tags)
		})
		if i < 0 {
			continue
		}
		base := gs[i]
		row := []string{name(g.target), strconv.Itoa(g.target.Lanes), grouped(float64(g.rate)), g.workload, speedCell(g.speed)}
		if base.speed != g.speed || len(g.counted) == 0 || len(base.counted) == 0 {
			t.add(append(row, "n/a, other disk speed", "n/a", "n/a")...)
		} else {
			for _, pick := range []func(fig) float64{
				func(x fig) float64 { return x.p50 }, func(x fig) float64 { return x.p99 }, func(x fig) float64 { return x.syncs },
			} {
				row = append(row, ratio(g.spread(pick).med, base.spread(pick).med))
			}
			t.add(row...)
		}
		runs = append(append(runs, g.runs...), base.runs...)
		shown = append(shown, g, base)
	}
	if len(t.rows) == 0 {
		return
	}
	b.WriteString("Each load against uniform-10k on the same target, lanes and rate: the ratio of the medians.\n\n")
	t.write(b)
	writeContext(b, runs, shown)
}

func writeAB(b *strings.Builder, gs []*group) {
	t := table{head: []string{"target", "lanes", "load", "rate", "B adds", "speed", "p50 B/A", "fsync per transfer B/A", "throughput B/A"}}
	var runs []*run
	var shown []*group
	for _, g := range gs {
		for _, a := range gs {
			if a == g || !sameBut(a, g) || a.workload != g.workload || len(a.target.Env) >= len(g.target.Env) {
				continue
			}
			var adds []string
			subset := true
			for k, v := range a.target.Env {
				subset = subset && g.target.Env[k] == v
			}
			for _, k := range slices.Sorted(maps.Keys(g.target.Env)) {
				if _, ok := a.target.Env[k]; !ok {
					adds = append(adds, k+"="+g.target.Env[k])
				}
			}
			if !subset {
				continue
			}
			row := []string{name(g.target), strconv.Itoa(g.target.Lanes), g.workload, grouped(float64(g.rate)), strings.Join(adds, " "), speedCell(g.speed)}
			if a.speed != g.speed || len(a.counted) == 0 || len(g.counted) == 0 {
				row = append(row, "n/a, other disk speed", "n/a", "n/a")
			} else {
				for _, pick := range []func(fig) float64{
					func(x fig) float64 { return x.p50 }, func(x fig) float64 { return x.syncs }, func(x fig) float64 { return x.throughput },
				} {
					row = append(row, ratio(g.spread(pick).med, a.spread(pick).med))
				}
			}
			t.add(row...)
			runs = append(append(runs, a.runs...), g.runs...)
			shown = append(shown, a, g)
		}
	}
	if len(t.rows) == 0 {
		return
	}
	t.write(b)
	writeContext(b, runs, shown)
}

func healthy(missing, m2 []*group) []*group {
	var out []*group
	for _, g := range missing {
		for _, h := range m2 {
			if sameBut(h, g) && h.workload == g.workload && !slices.Contains(out, h) {
				out = append(out, h)
			}
		}
	}
	return out
}

func writeLoop(b *strings.Builder, gs []*group) {
	t := table{head: append([]string{"measurement", "target", "lanes", "load", "rate", "role", "speed", "runs"}, loopPosts...)}
	var runs []*run
	var shown []*group
	for _, g := range gs {
		if g.target.Kind != "ledger" || g.m != "m2" && g.m != "m3" && g.m != "m7" {
			continue
		}
		byRole := make(map[string][]map[string]float64)
		for _, r := range g.counted {
			for role, l := range loopsOf(r.f, func(i int) bool { return counts(r.f, i, g.speed) }) {
				if s := l.shares(); s != nil {
					byRole[role] = append(byRole[role], s)
				}
			}
		}
		for _, role := range []string{"leader", "follower"} {
			if len(byRole[role]) == 0 {
				continue
			}
			row := []string{g.m, name(g.target), strconv.Itoa(g.target.Lanes), g.workload, grouped(float64(g.rate)), role, speedCell(g.speed), strconv.Itoa(len(byRole[role]))}
			for _, p := range loopPosts {
				var xs []float64
				for _, s := range byRole[role] {
					xs = append(xs, s[p])
				}
				row = append(row, median(xs).show(percent))
			}
			t.add(row...)
		}
		if len(byRole) > 0 {
			runs = append(runs, g.runs...)
			shown = append(shown, g)
		}
	}
	if len(t.rows) == 0 {
		return
	}
	b.WriteString("## Time of the node loop\n\n")
	b.WriteString("Where the loop of a node spends its time, in percent of the time the node was up, from the counters each node " +
		"reports once a second, added up over the counted seconds of a run. The three fsync columns are timed calls. " +
		"\"computing in Process\" is the time in Process minus all fsync, \"reading, sending, answering\" is the time " +
		"outside Process and outside waiting for work. The followers of one run are added up.\n\n")
	t.write(b)
	writeContext(b, runs, shown)
}

func writeProfiles(b *strings.Builder, runs []*run) {
	t := table{head: append(append([]string{"run", "node", "sampled s"}, posts...), "largest three")}
	var shown []*run
	var problems []string
	for _, r := range runs {
		for _, tr := range r.traces {
			s, err := countTraces(tr.text)
			if err != nil {
				problems = append(problems, fmt.Sprintf("%s, %s: %v", r.f.ID, tr.node, err))
				continue
			}
			row := []string{r.f.ID, tr.node, strconv.FormatFloat(s.total.Seconds(), 'f', 2, 64)}
			for _, p := range posts {
				row = append(row, percent(s.of(p)))
			}
			t.add(append(row, strings.Join(s.top(3), ", "))...)
			if !slices.Contains(shown, r) {
				shown = append(shown, r)
			}
		}
	}
	if len(t.rows) == 0 && len(problems) == 0 {
		return
	}
	b.WriteString("## CPU profile\n\n")
	b.WriteString("Where the CPU time of a node goes, in percent of the sampled CPU time. Each sample goes to exactly one " +
		"column: its stack is walked from the leaf to the root and the first frame that belongs to a column decides. " +
		"Stacks without such a frame go to \"kernel\" when they hold a system call, to \"runtime\" when they hold the Go " +
		"runtime, and to \"rest\" otherwise. A CPU profile does not see the time a node sleeps in fsync; that time is in the " +
		"table of the node loop.\n\n")
	t.write(b)
	for _, p := range problems {
		fmt.Fprintf(b, "Not read: %s.\n\n", p)
	}
	if len(shown) > 0 {
		writeContext(b, shown, groups(shown))
	}
}

func writeSnapshots(b *strings.Builder, runs []*run) {
	t := table{head: []string{"run", "nodes", "accounts", "valid", "snapshot MB", "longest round ms", "ms per 100 MB", "worst second p99 ms", "term changed", "stopped node"}}
	var shown []*run
	for _, r := range runs {
		if r.f.Measurement != "m4" {
			continue
		}
		var longest, size uint64
		var worst float64
		for _, s := range r.f.Seconds {
			if s.Phase != load.Window.String() {
				continue
			}
			for _, p := range s.Parts {
				longest = max(longest, p.Counters["slowest"])
				size = max(size, p.Counters["snapshot_bytes"])
			}
			worst = max(worst, nanos(s.P99))
		}
		mb, per := "n/a", "n/a"
		if size > 0 {
			mb, per = grouped(float64(size)/1e6), plainMillis(float64(longest)*1e8/float64(size))
		}
		changed := "no"
		if r.f.TermChanged() {
			changed = "yes"
		}
		stopped := "none"
		if bo := r.f.Bounce; bo != nil {
			stopped = bo.Node + ", a " + bo.Role + ", caught up from the log"
			if bo.Snapshot > 0 {
				stopped = bo.Node + ", a " + bo.Role + ", got a snapshot of " + grouped(float64(bo.Snapshot)/1e6) + " MB"
			}
		}
		t.add(r.f.ID, strconv.Itoa(r.f.Target.Nodes), grouped(float64(r.f.Load.Accounts)), yesNo(r.f.Verdict.Valid),
			mb, plainMillis(float64(longest)), per, millis(r.f.Verdict.Horizon)(worst), changed, stopped)
		shown = append(shown, r)
	}
	b.WriteString("## Snapshot pause (m4)\n\n")
	b.WriteString("How long does a node stop for a snapshot, and does that cost the lead? \"longest round\" is the slowest " +
		"single pass of the node loop in any second of the window, and \"worst second\" the highest p99 of a second. Both " +
		"come from every second of the window, valid or not, because a pause can make its own second invalid. \"snapshot MB\" " +
		"is the largest snapshot file of a node in the window and \"ms per 100 MB\" the longest round divided by it. In e one " +
		"follower stops during the window and comes back; the last column names it and says whether it got a snapshot from the " +
		"leader, as its own log reports it, or caught up from the log. Each run stands on its own row.\n\n")
	t.write(b)
	writeContext(b, shown, groups(shown))
}

func yesNo(v bool) string {
	if v {
		return "yes"
	}
	return "no"
}

func writeRuns(b *strings.Builder, runs []*run) {
	gs := groups(runs)
	counted := make(map[*run]bool)
	for _, g := range gs {
		for _, r := range g.counted {
			counted[r] = true
		}
	}
	t := table{head: []string{"file", "measurement", "target", "lanes", "load", "rate", "pass", "started", "speed", "valid", "counted", "seconds", "left out", "saturated", "reasons"}}
	for _, r := range runs {
		f := r.f
		count := "yes"
		switch {
		case !f.Verdict.Valid:
			count = "no, invalid"
		case !counted[r]:
			count = "no, other disk speed"
		}
		sat := "no"
		if f.Verdict.Saturated {
			sat = "yes, limit " + f.Verdict.Limit
		}
		why := strings.Join(append(slices.Clone(f.Verdict.Reasons), f.Verdict.Problems...), "; ")
		in := 0
		if v := f.Verdict.Speed; v.Rank() > 0 {
			in = bandOf(f, v).Seconds
		}
		secs := secondsCell(in, in+f.Verdict.Excluded, nanos(f.Verdict.ExcludedP99), f.Verdict.Horizon, f.Verdict.Throttled)
		t.add(r.name, f.Measurement, name(f.Target), strconv.Itoa(f.Target.Lanes), f.Load.Workload, grouped(float64(f.Load.Rate)),
			strconv.Itoa(f.Pass), f.Started.UTC().Format("2006-01-02 15:04"), f.Verdict.Speed.String(), yesNo(f.Verdict.Valid), count, secs, f.LeftOut(), sat, why)
	}
	b.WriteString("## Runs\n\n")
	b.WriteString("Every raw file, valid or not. Only the runs marked as counted enter the figures above. \"left out\" counts the " +
		"window seconds outside the figures of a run by their reasons. In a run with a disk speed, a second with fewer than 20 " +
		"flushes is left out when the target used at least half a core in it, and stalls the run when it used less.\n\n")
	t.write(b)
	writeContext(b, runs, gs)
}
